static bool validate_utf8(const unsigned char *bytes, std::size_t length) {
  std::size_t index = 0;

  for (;;) {
    while (index < length && bytes[index] < 0x80) {
      ++index;
    }

    if (index == length) {
      return true;
    }

    const unsigned char lead = bytes[index];
    if (lead < 0xC2 || lead > 0xF4) {
      return false;
    }

    const std::size_t remaining = length - index;
    if (lead <= 0xDF) {
      if (remaining < 2) {
        return false;
      }
      const unsigned char second = bytes[index + 1];
      if ((second & 0xC0) != 0x80) {
        return false;
      }
      index += 2;
    } else if (lead <= 0xEF) {
      if (remaining < 3) {
        return false;
      }
      const unsigned char second = bytes[index + 1];
      const unsigned char third = bytes[index + 2];
      if ((second & 0xC0) != 0x80 || (third & 0xC0) != 0x80 ||
          (lead == 0xE0 && second < 0xA0) ||
          (lead == 0xED && second >= 0xA0)) {
        return false;
      }
      index += 3;
    } else {
      if (remaining < 4) {
        return false;
      }
      const unsigned char second = bytes[index + 1];
      const unsigned char third = bytes[index + 2];
      const unsigned char fourth = bytes[index + 3];
      if ((second & 0xC0) != 0x80 || (third & 0xC0) != 0x80 ||
          (fourth & 0xC0) != 0x80 ||
          (lead == 0xF0 && second < 0x90) ||
          (lead == 0xF4 && second > 0x8F)) {
        return false;
      }
      index += 4;
    }
  }
}

extern "C" void run(const void *input1, const void *input2, void *output,
